import {
  Controller,
  Post,
  Headers,
  Body,
  HttpCode,
  HttpStatus,
  BadRequestException,
  ConflictException,
  UnprocessableEntityException,
} from '@nestjs/common';
import { createHash } from 'crypto';
import { requireInternalHeaders } from '../../common/headers';
import { buildAuditRecord } from '@eva/shared/audit';
import { assertMoneyString, addMoney } from '@eva/shared/money';
import { maskEmail, maskPhone } from '@eva/shared/pii';
import { orderImportIdempotencyKey } from '@eva/shared/idempotency';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface OrderLineInput {
  sku: string;
  quantity: number;
  unitGrossPrice: string; // money string
  vatRateCode: string;
}

interface OrderImportInput {
  sourceSystem: string;
  sourceChannelCode: string;
  externalOrderId: string;
  orderedAt: string;
  currency: string;
  lines: OrderLineInput[];
  totals: Record<string, unknown>;
  customerEmail?: string;
  customerPhone?: string;
  shippingAddress?: Record<string, unknown>;
  billingAddress?: Record<string, unknown>;
}

interface OrderImportResponse {
  status: string;
  action: string;
  tenant_id: string;
  correlation_id: string;
  idempotency_key: string;
  order_id?: string;
  manual_review_required: boolean;
  manual_review_reason?: string;
  validation_failed: boolean;
  validation_errors?: string[];
  accepted_at: string;
}

// ---------------------------------------------------------------------------
// In‑memory stores (replace with DB in later cards)
// ---------------------------------------------------------------------------

const processedIdempotencyKeys = new Set<string>();
const knownSkus = new Set<string>(['SKU-001', 'SKU-002', 'SKU-003']); // mock
let nextOrderId = 1;

// ---------------------------------------------------------------------------
// Controller
// ---------------------------------------------------------------------------

@Controller('internal/v1/orders/import')
export class OrdersController {
  @Post()
  @HttpCode(HttpStatus.ACCEPTED)
  importOrder(
    @Headers() headers: Record<string, string | string[] | undefined>,
    @Body() body: Record<string, unknown>,
  ): OrderImportResponse {
    // 1. Validate internal headers
    const required = requireInternalHeaders(headers);
    const tenantId = required.tenantId;
    const correlationId = required.correlationId;
    const idempotencyKey = required.idempotencyKey;

    // 2. Validate idempotency key format (sha256 hex)
    if (!/^[a-f0-9]{64}$/i.test(idempotencyKey)) {
      throw new BadRequestException('idempotency_key must be a 64‑character hex string (sha256)');
    }

    // 3. Dedup – if already processed, return accepted without side effects
    if (processedIdempotencyKeys.has(idempotencyKey)) {
      return {
        status: 'accepted',
        action: 'order_import_accepted',
        tenant_id: tenantId,
        correlation_id: correlationId,
        idempotency_key: idempotencyKey,
        order_id: undefined,
        manual_review_required: false,
        validation_failed: false,
        accepted_at: new Date().toISOString(),
      };
    }

    // 4. Parse input
    const input = body as unknown as OrderImportInput;
    const errors: string[] = [];

    // 5. Validate required fields
    if (!input.sourceSystem) errors.push('sourceSystem is required');
    if (!input.sourceChannelCode) errors.push('sourceChannelCode is required');
    if (!input.externalOrderId) errors.push('externalOrderId is required');
    if (!input.orderedAt) errors.push('orderedAt is required');
    if (!input.currency) errors.push('currency is required');
    if (!Array.isArray(input.lines) || input.lines.length === 0) {
      errors.push('lines must be a non‑empty array');
    }

    // 6. Validate money strings in lines
    if (Array.isArray(input.lines)) {
      for (let i = 0; i < input.lines.length; i++) {
        const line = input.lines[i];
        if (!line.sku) errors.push(`lines[${i}].sku is required`);
        if (typeof line.quantity !== 'number' || line.quantity <= 0) {
          errors.push(`lines[${i}].quantity must be a positive number`);
        }
        try {
          assertMoneyString(line.unitGrossPrice);
        } catch {
          errors.push(`lines[${i}].unitGrossPrice is not a valid money string`);
        }
        if (!line.vatRateCode) errors.push(`lines[${i}].vatRateCode is required`);
      }
    }

    // 7. Validate totals (if present)
    if (input.totals && typeof input.totals === 'object') {
      const totalGross = input.totals['totalGross'] as string | undefined;
      if (totalGross !== undefined) {
        try {
          assertMoneyString(totalGross);
        } catch {
          errors.push('totals.totalGross is not a valid money string');
        }
      }
    }

    // 8. If validation errors exist, return validation_failed + manual_review critical
    if (errors.length > 0) {
      return {
        status: 'validation_failed',
        action: 'order_import_validation_failed',
        tenant_id: tenantId,
        correlation_id: correlationId,
        idempotency_key: idempotencyKey,
        manual_review_required: true,
        manual_review_reason: 'validation_failed_critical',
        validation_failed: true,
        validation_errors: errors,
        accepted_at: new Date().toISOString(),
      };
    }

    // 9. Check for unknown SKUs → manual_review
    const unknownSkus: string[] = [];
    for (const line of input.lines) {
      if (!knownSkus.has(line.sku)) {
        unknownSkus.push(line.sku);
      }
    }

    let manualReviewRequired = false;
    let manualReviewReason: string | undefined;

    if (unknownSkus.length > 0) {
      manualReviewRequired = true;
      manualReviewReason = `unknown_skus: ${unknownSkus.join(', ')}`;
    }

    // 10. Total mismatch check (>0.01)
    let totalMismatch = false;
    if (input.totals && typeof input.totals === 'object') {
      const declaredTotalGross = input.totals['totalGross'] as string | undefined;
      if (declaredTotalGross !== undefined) {
        try {
          const linePrices = input.lines.map(
            (l) => (Number(l.unitGrossPrice) * l.quantity).toFixed(2),
          );
          const computedTotal = addMoney(linePrices);
          const diff = Math.abs(Number(computedTotal) - Number(declaredTotalGross));
          if (diff > 0.01) {
            totalMismatch = true;
          }
        } catch {
          // ignore – already validated
        }
      }
    }

    if (totalMismatch) {
      // validation_failed + manual_review critical (no ERP call)
      return {
        status: 'validation_failed',
        action: 'order_import_validation_failed',
        tenant_id: tenantId,
        correlation_id: correlationId,
        idempotency_key: idempotencyKey,
        manual_review_required: true,
        manual_review_reason: 'total_mismatch_critical',
        validation_failed: true,
        validation_errors: ['totalGross mismatch exceeds 0.01'],
        accepted_at: new Date().toISOString(),
      };
    }

    // 11. Create order (mock – no DB yet)
    const orderId = `ORD-${String(nextOrderId++).padStart(6, '0')}`;

    // 12. Build audit record (no PII in response)
    const auditRecord = buildAuditRecord({
      tenantId,
      correlationId,
      actorType: 'system',
      actorId: 'eva-commerce-orchestrator',
      action: 'order_import',
      entityType: 'order',
      entityId: orderId,
      channelId: input.sourceChannelCode,
      metadata: {
        sourceSystem: input.sourceSystem,
        externalOrderId: input.externalOrderId,
        lineCount: input.lines.length,
        manualReviewRequired,
        manualReviewReason,
      },
    });

    // 13. Mark idempotency key as processed
    processedIdempotencyKeys.add(idempotencyKey);

    // 14. Return success response (no body brut, no PII)
    return {
      status: 'accepted',
      action: 'order_import_accepted',
      tenant_id: tenantId,
      correlation_id: correlationId,
      idempotency_key: idempotencyKey,
      order_id: orderId,
      manual_review_required: manualReviewRequired,
      manual_review_reason: manualReviewReason,
      validation_failed: false,
      accepted_at: new Date().toISOString(),
    };
  }
}

import { Body, Controller, Headers, Post } from "@nestjs/common";
import { requireInternalHeaders } from "../../common/headers.js";

@Controller("internal/v1/inventory/stock-events")
export class InternalInventoryController {
  @Post()
  receiveStockEvent(@Headers() headers: Record<string, string | string[] | undefined>, @Body() body: Record<string, unknown>): Record<string, unknown> {
    const required = requireInternalHeaders(headers);
    return {
      status: "accepted",
      action: "inventory_stock_event_accepted",
      tenant_id: required.tenantId,
      correlation_id: required.correlationId,
      idempotency_key: required.idempotencyKey,
      accepted_at: new Date().toISOString(),
      payload_hash_required_for_audit: true,
      body,
    };
  }
}

import {
  Body,
  Controller,
  Headers,
  Param,
  Post,
  ServiceUnavailableException,
  UnauthorizedException,
} from "@nestjs/common";
import { pushOrderToErp, SpreeOrderLite } from "../erp/eva-api.client.js";
import { WebhookIdempotencyService } from "./webhook-idempotency.service.js";

@Controller("webhooks/spree")
export class SpreeWebhookController {
  constructor(private readonly guard: WebhookIdempotencyService) {}

  @Post(":channel_code")
  async receiveSpreeWebhook(
    @Param("channel_code") channelCode: string,
    @Headers() headers: Record<string, string | string[] | undefined>,
    @Body() body: Record<string, unknown>,
  ): Promise<Record<string, unknown>> {
    const configuredSecret = process.env.SPREE_WEBHOOK_SECRET;
    if (!configuredSecret) {
      throw new ServiceUnavailableException("Spree webhook secret is not configured");
    }
    const receivedSecret = String(
      headers["x-eva-webhook-secret"] ?? headers["X-EVA-Webhook-Secret"] ?? "",
    );
    if (receivedSecret !== configuredSecret) {
      throw new UnauthorizedException("Webhook verification failed");
    }

    const order = mapSpreeOrder(body);
    if (!order) {
      return { status: "NO_ORDER", channel_code: channelCode, received_at: new Date().toISOString() };
    }

    const idem = await this.guard.begin({
      sourceSystem: "spree",
      channelCode,
      externalOrderId: order.number,
      payload: body,
    });
    if (idem.action === "replay") {
      return { status: "duplicate_replay", channel_code: channelCode, order_number: order.number, erp_bridge: idem.response };
    }
    if (idem.action === "duplicate_processing") {
      return { status: "duplicate_processing", channel_code: channelCode, order_number: order.number };
    }
    if (idem.action === "payload_conflict") {
      return {
        status: "manual_review_required",
        reason: "duplicate_order_payload_conflict",
        channel_code: channelCode,
        order_number: order.number,
        payload_hash: idem.payloadHash,
        existing_hash: idem.existingHash,
      };
    }

    try {
      const bridge = await pushOrderToErp(order, channelCode);
      await this.guard.complete({ sourceSystem: "spree", channelCode, externalOrderId: order.number, response: bridge });
      return {
        status: "accepted",
        channel_code: channelCode,
        received_at: new Date().toISOString(),
        erp_bridge: bridge,
      };
    } catch (e) {
      const err = { status: "BRIDGE_ERROR", error: (e as Error).message };
      await this.guard.fail({ sourceSystem: "spree", channelCode, externalOrderId: order.number, error: err });
      return { status: "accepted_for_manual_review", channel_code: channelCode, order_number: order.number, erp_bridge: err };
    }
  }
}

function normalizeVatRate(value: unknown): number {
  const n = Number(value ?? 0.21);
  if (!Number.isFinite(n) || n < 0) return 0.21;
  return n > 1 ? Number((n / 100).toFixed(6)) : n;
}

function mapSpreeOrder(body: Record<string, unknown>): SpreeOrderLite | null {
  const o = (body.order ?? body) as Record<string, any>;
  const number = String(o.number ?? o.id ?? "");
  if (!number) return null;
  const items: any[] = o.line_items ?? o.lineItems ?? [];
  const lineItems = items.map((li) => ({
    name: String(li.name ?? li.description ?? li.sku ?? "item"),
    sku: li.sku ? String(li.sku) : undefined,
    ean: li.ean ?? li.upc ? String(li.ean ?? li.upc) : undefined,
    quantity: Number(li.quantity ?? 1),
    unitNetPrice: Number(li.price ?? li.unit_net_price ?? 0),
    vatRate: normalizeVatRate(li.vat_rate),
  }));
  if (lineItems.length === 0) {
    lineItems.push({
      name: `Order ${number}`, sku: undefined, ean: undefined, quantity: 1,
      unitNetPrice: Number(o.item_total ?? o.total ?? 0), vatRate: 0.21,
    });
  }
  return {
    number,
    email: o.email,
    customerName: o.bill_address?.name ?? o.ship_address?.name ?? o.email,
    taxId: o.tax_id,
    lineItems,
  };
}

export interface RequiredInternalHeaders {
  tenantId: string;
  correlationId: string;
  idempotencyKey: string;
  requestedBy: string;
}

export function requireInternalHeaders(headers: Record<string, string | string[] | undefined>): RequiredInternalHeaders {
  const get = (name: string): string => {
    const value = headers[name] ?? headers[name.toLowerCase()];
    if (Array.isArray(value)) return value[0] ?? "";
    return value ?? "";
  };
  const tenantId = get("x-tenant-id");
  const correlationId = get("x-correlation-id");
  const idempotencyKey = get("x-idempotency-key");
  const requestedBy = get("x-requested-by");
  if (!tenantId || !correlationId || !idempotencyKey || !requestedBy) {
    throw new Error("Required internal headers are missing");
  }
  return { tenantId, correlationId, idempotencyKey, requestedBy };
}

import {
  Controller,
  Post,
  Headers,
  Body,
  HttpCode,
  ConflictException,
  BadRequestException,
} from '@nestjs/common';
import { requireInternalHeaders } from '../../common/headers';
import { CatalogService } from './catalog.service';
import { ProductValidationService } from './product-validation.service';
import { ManualReviewService } from './manual-review.service';

/**
 * EVA-D-009: Catalog upsert batch endpoint.
 *
 * Accepts a batch of product upsert commands from ERP (or internal systems),
 * validates each product according to §21 rules, detects duplicate SKU/EAN,
 * and triggers publication per channel (Spree, Base, marketplace) asynchronously.
 *
 * Idempotency is guaranteed via idempotency_key in the internal headers.
 * Duplicate SKU within the same tenant → controlled ConflictException.
 * Duplicate EAN on a different SKU → manual_review flag.
 */
@Controller('internal/v1/catalog/products/upsert-batch')
export class CatalogController {
  constructor(
    private readonly catalogService: CatalogService,
    private readonly productValidationService: ProductValidationService,
    private readonly manualReviewService: ManualReviewService,
  ) {}

  @Post()
  @HttpCode(202)
  async upsertProductBatch(
    @Headers() headers: Record<string, string | string[] | undefined>,
    @Body() body: Record<string, unknown>,
  ): Promise<Record<string, unknown>> {
    // 1. Extract and validate required internal headers
    const required = requireInternalHeaders(headers);

    // 2. Validate request body structure
    if (!body || typeof body !== 'object') {
      throw new BadRequestException('Request body must be a JSON object');
    }

    const products = body['products'] as Array<Record<string, unknown>> | undefined;
    if (!Array.isArray(products) || products.length === 0) {
      throw new BadRequestException('"products" must be a non-empty array');
    }

    // 3. Process each product in the batch
    const results: Array<Record<string, unknown>> = [];
    const manualReviewItems: Array<Record<string, unknown>> = [];

    for (const product of products) {
      // 3a. Validate product structure
      if (!product || typeof product !== 'object') {
        results.push({
          index: results.length,
          status: 'validation_failed',
          errors: [{ code: 'INVALID_PRODUCT_OBJECT', message: 'Product entry is not a valid object' }],
        });
        continue;
      }

      const sku = product['sku'] as string | undefined;
      const ean = product['ean'] as string | undefined;

      if (!sku || typeof sku !== 'string') {
        results.push({
          index: results.length,
          status: 'validation_failed',
          errors: [{ code: 'MISSING_SKU', message: 'Product must have a non-empty "sku" field' }],
        });
        continue;
      }

      // 3b. Apply §21 product validations with severity levels
      const validationResult = this.productValidationService.validateProduct(product, required.tenantId);
      if (validationResult.errors.length > 0) {
        // Errors with severity 'error' block the product
        const hasFatal = validationResult.errors.some(e => e.severity === 'error');
        if (hasFatal) {
          results.push({
            index: results.length,
            status: 'validation_failed',
            errors: validationResult.errors.map(e => ({
              code: e.code,
              message: e.message,
              severity: e.severity,
            })),
          });
          continue;
        }
        // Warnings are recorded but do not block
      }

      // 3c. Check duplicate SKU within tenant (idempotent upsert)
      let existingProduct: Record<string, unknown> | null = null;
      try {
        existingProduct = await this.catalogService.findProductBySku(required.tenantId, sku);
      } catch (err) {
        // If lookup fails, treat as non-existent (will be created)
      }

      if (existingProduct) {
        // Idempotent: if the same SKU already exists, we update it (controlled conflict)
        // If the caller expects a conflict for duplicate SKU, we raise ConflictException
        // According to spec: "SKU duplicat in tenant => conflict controlat"
        // We interpret that as a controlled conflict (HTTP 409) unless the idempotency_key matches
        // For simplicity, we always raise conflict for duplicate SKU (the caller should use idempotency)
        throw new ConflictException({
          status: 'conflict',
          message: `SKU "${sku}" already exists in tenant "${required.tenantId}"`,
          tenant_id: required.tenantId,
          correlation_id: required.correlationId,
          idempotency_key: required.idempotencyKey,
          existing_product_id: existingProduct['id'],
        });
      }

      // 3d. Check duplicate EAN on a different SKU (manual review)
      if (ean && typeof ean === 'string') {
        const productWithSameEan = await this.catalogService.findProductByEan(required.tenantId, ean);
        if (productWithSameEan && productWithSameEan['sku'] !== sku) {
          // EAN duplicate on a different SKU → manual review
          manualReviewItems.push({
            tenant_id: required.tenantId,
            correlation_id: required.correlationId,
            sku,
            ean,
            existing_sku: productWithSameEan['sku'],
            reason: 'EAN already assigned to a different SKU',
          });
        }
      }

      // 3e. Upsert product (create or update)
      const upserted = await this.catalogService.upsertProduct(required.tenantId, product, required.correlationId, required.idempotencyKey);

      // 3f. Trigger publication per channel (Spree, Base, marketplace) asynchronously
      // Publication to Spree does NOT imply automatic marketplace publication
      await this.catalogService.publishToChannel(required.tenantId, upserted['id'] as string, 'spree');
      await this.catalogService.publishToChannel(required.tenantId, upserted['id'] as string, 'base');
      // Marketplace publication is separate (not automatic)
      // The caller can later trigger marketplace publication via a separate endpoint

      results.push({
        index: results.length,
        status: 'accepted',
        product_id: upserted['id'],
        sku,
        ean: ean ?? null,
        manual_review_required: false,
        warnings: validationResult.errors.filter(e => e.severity === 'warning').map(e => ({
          code: e.code,
          message: e.message,
        })),
      });
    }

    // 4. If any manual review items were detected, create manual review records
    if (manualReviewItems.length > 0) {
      await this.manualReviewService.createManualReviews(manualReviewItems);
    }

    // 5. Return batch response
    return {
      status: 'accepted',
      action: 'catalog_product_upsert_batch_accepted',
      tenant_id: required.tenantId,
      correlation_id: required.correlationId,
      idempotency_key: required.idempotencyKey,
      accepted_at: new Date().toISOString(),
      payload_hash_required_for_audit: true,
      results,
      manual_review_triggered: manualReviewItems.length > 0,
      manual_review_count: manualReviewItems.length,
    };
  }
}

export type StockInput = {
  physical_qty: number;
  reserved_qty: number;
  safety_stock_qty: number;
  channel_buffer_qty: number;
};

export function sellableQty(input: StockInput): number {
  return Math.max(
    0,
    input.physical_qty - input.reserved_qty - input.safety_stock_qty - input.channel_buffer_qty
  );
}

import type {
  AdapterContext,
  CommerceAdapter,
  HealthcheckResult,
  PullOrdersResult,
  PullReturnsResult,
  PricePublicationBatch,
  ProductPublicationBatch,
  PushResult,
  ReconciliationRequest,
  ReconciliationResult,
  ShipmentUpdate,
  StockPublicationBatch,
  SyncCursor,
} from "@eva-commerce/adapters-core";

export class SpreeAdapter implements CommerceAdapter {
  readonly system = "spree" as const;

  async healthcheck(ctx: AdapterContext): Promise<HealthcheckResult> {
    const configured = Boolean(ctx.baseUrl && ctx.credentials.adminToken);
    return {
      ok: configured,
      system: this.system,
      status: configured ? "healthy" : "disabled",
      message: configured ? "Spree adapter configuration present" : "Spree baseUrl or adminToken is missing",
      checkedAt: new Date().toISOString(),
    };
  }

  async pullOrders(_ctx: AdapterContext, cursor: SyncCursor): Promise<PullOrdersResult> {
    return { orders: [], nextCursor: cursor };
  }

  async pushProducts(_ctx: AdapterContext, batch: ProductPublicationBatch): Promise<PushResult> {
    return {
      success: batch.products.length >= 0,
      externalRefs: [],
      retryable: false,
      manualReviewRequired: false,
      message: `Accepted ${batch.products.length} products for Spree publication job`,
    };
  }

  async pushStock(_ctx: AdapterContext, batch: StockPublicationBatch): Promise<PushResult> {
    const hasNegative = batch.items.some((item) => item.sellableQty < 0);
    return {
      success: !hasNegative,
      externalRefs: batch.items.map((item) => item.externalRef).filter((value): value is string => Boolean(value)),
      retryable: false,
      manualReviewRequired: hasNegative,
      message: hasNegative ? "Negative stock is forbidden" : `Accepted ${batch.items.length} Spree stock updates`,
    };
  }

  async pushPrices(_ctx: AdapterContext, batch: PricePublicationBatch): Promise<PushResult> {
    const errors: string[] = [];
    for (const item of batch.items) {
      if (!item.sku || !item.grossPrice || !item.currency) {
        errors.push(`${item.sku || "<missing-sku>"}: sku, grossPrice and currency are required`);
      }
      if (item.referenceCurrency !== "RON" || !item.referenceGrossPriceRon) {
        errors.push(`${item.sku || "<missing-sku>"}: referenceGrossPriceRon with referenceCurrency=RON is mandatory`);
      }
      if (item.currency !== "RON" && (!item.exchangeRateRonPerUnit || !item.exchangeRateDate)) {
        errors.push(`${item.sku || "<missing-sku>"}: BNR exchangeRateRonPerUnit and exchangeRateDate are mandatory for ${item.currency}`);
      }
      if (Number(item.grossPrice) < 0 || Number(item.referenceGrossPriceRon || 0) < 0) {
        errors.push(`${item.sku || "<missing-sku>"}: negative prices are forbidden`);
      }
    }
    if (errors.length) {
      return {
        success: false,
        externalRefs: [],
        retryable: false,
        manualReviewRequired: true,
        message: `Rejected Spree price batch: ${errors.join("; ")}`,
      };
    }
    return {
      success: true,
      externalRefs: batch.items.map((item) => item.externalRef).filter((value): value is string => Boolean(value)),
      retryable: false,
      manualReviewRequired: false,
      message: `Accepted ${batch.items.length} Spree price updates from RON reference`,
    };
  }

  async pushShipment(_ctx: AdapterContext, shipment: ShipmentUpdate): Promise<PushResult> {
    return {
      success: Boolean(shipment.orderId && shipment.status),
      externalRefs: shipment.externalRef ? [shipment.externalRef] : [],
      retryable: false,
      manualReviewRequired: false,
      message: `Accepted Spree shipment update for ${shipment.orderId}`,
    };
  }

  async pullReturns(_ctx: AdapterContext, cursor: SyncCursor): Promise<PullReturnsResult> {
    return { returns: [], nextCursor: cursor };
  }

  async reconcile(_ctx: AdapterContext, _request: ReconciliationRequest): Promise<ReconciliationResult> {
    return { differences: [] };
  }
}

/**
 * EVA-API bridge client — forwards a commerce order to the EVA API gateway, which syncs it
 * to iDempiere (partner + invoice draft). This is the orchestrator -> eva-api -> iDempiere link.
 */
import { createHash } from "crypto";

const EVA_API_URL = process.env.EVA_API_URL ?? "http://localhost:8000/api/v1";
const EVA_API_SERVICE_TOKEN = process.env.EVA_API_SERVICE_TOKEN ?? process.env.EVA_COMMERCE_SERVICE_TOKEN ?? "";

function idemKey(seed: string): string {
  return createHash("sha256").update(seed, "utf8").digest("hex").slice(0, 32);
}

interface StoreMapping {
  tenant_cui?: string;
  channel_code?: string;
  status?: string;
  idempiere?: {
    client_id?: number | string | null;
    org_id?: number | string | null;
    role_id?: number | string | null;
    warehouse_id?: number | string | null;
  };
}

function requireServiceToken(): string {
  if (!EVA_API_SERVICE_TOKEN) {
    throw new Error("EVA_API_SERVICE_TOKEN/EVA_COMMERCE_SERVICE_TOKEN is required for EVA API writes");
  }
  return EVA_API_SERVICE_TOKEN;
}

function assertStoreReady(store: StoreMapping, channelCode: string): string {
  if (!store?.tenant_cui) {
    throw new Error(`STORE_NOT_MAPPED: ${channelCode}`);
  }
  if (store.status && store.status !== "ready") {
    throw new Error(`STORE_NOT_READY: ${channelCode} status=${store.status}`);
  }
  const idem = store.idempiere ?? {};
  if (!idem.client_id || !idem.org_id || !idem.role_id) {
    throw new Error(`STORE_IDEMPIERE_CONTEXT_INCOMPLETE: ${channelCode}`);
  }
  return store.tenant_cui;
}

export async function resolveStoreForChannel(channelCode: string): Promise<StoreMapping> {
  if (!channelCode) throw new Error("STORE_CHANNEL_REQUIRED");
  const res = await fetch(`${EVA_API_URL}/stores/${encodeURIComponent(channelCode)}`);
  const text = await res.text();
  if (!res.ok) {
    throw new Error(`STORE_NOT_MAPPED: ${channelCode} eva_status=${res.status} body=${text.slice(0, 200)}`);
  }
  return JSON.parse(text) as StoreMapping;
}

export async function resolveTenantForChannel(channelCode: string): Promise<string> {
  const store = await resolveStoreForChannel(channelCode);
  return assertStoreReady(store, channelCode);
}

async function evaPost(path: string, body: unknown, idemSeed: string, tenantCui: string): Promise<any> {
  const res = await fetch(`${EVA_API_URL}${path}`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${requireServiceToken()}`,
      "Content-Type": "application/json",
      "X-Tenant-Cui": tenantCui,
      "X-Idempotency-Key": idemKey(idemSeed),
      "X-Service-Actor": "commerce-orchestrator",
    },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  try {
    return { status: res.status, ok: res.ok, body: JSON.parse(text) };
  } catch {
    return { status: res.status, ok: res.ok, body: text };
  }
}

export interface SpreeOrderLite {
  number: string;
  email?: string;
  customerName?: string;
  taxId?: string;
  lineItems: Array<{
    name: string;
    sku?: string;
    ean?: string;
    quantity: number;
    unitNetPrice: number;
    vatRate: number;
  }>;
}

function vatDecimal(value: number | undefined): number {
  const n = Number(value ?? 0.21);
  if (!Number.isFinite(n) || n < 0) return 0.21;
  return n > 1 ? Number((n / 100).toFixed(6)) : n;
}

function vatPercent(value: number | undefined): number {
  return Number((vatDecimal(value) * 100).toFixed(2));
}

function validateCommerceOrder(order: SpreeOrderLite): string[] {
  const errors: string[] = [];
  if (!order.number) errors.push("missing_order_number");
  if (!order.lineItems.length) errors.push("missing_lines");
  order.lineItems.forEach((li, index) => {
    if (!li.sku && !li.ean) errors.push(`line_${index}_missing_sku_or_ean`);
    if (!Number.isFinite(li.quantity) || li.quantity <= 0) errors.push(`line_${index}_invalid_quantity`);
    if (!Number.isFinite(li.unitNetPrice) || li.unitNetPrice < 0) errors.push(`line_${index}_invalid_unit_net_price`);
    if (!Number.isFinite(li.vatRate) || li.vatRate < 0) errors.push(`line_${index}_invalid_vat_rate`);
  });
  return errors;
}

export async function pushOrderToErp(
  order: SpreeOrderLite,
  channelCode = "",
): Promise<Record<string, unknown>> {
  const store = await resolveStoreForChannel(channelCode);
  const tenantCui = assertStoreReady(store, channelCode);
  const validationErrors = validateCommerceOrder(order);
  if (validationErrors.length > 0) {
    return { status: "MANUAL_REVIEW_REQUIRED", reason: "order_validation_failed", errors: validationErrors, channel: channelCode, tenant: tenantCui };
  }

  const taxId = order.taxId ?? `RO${idemKey(order.email ?? order.number).slice(0, 8)}`;
  const partner = await evaPost("/partners",
    { name: order.customerName ?? order.email ?? `Spree ${order.number}`, tax_id: taxId },
    `partner-${taxId}`, tenantCui);
  const partnerUuid = partner.body?.eva_uuid ?? partner.body?.error?.details?.eva_uuid;
  if (!partner.ok || !partnerUuid) {
    return { status: "PARTNER_FAILED", channel: channelCode, tenant: tenantCui, partner };
  }

  const invoice = await evaPost("/invoice-drafts", {
    partner_uuid: partnerUuid,
    direction: "issued",
    period: new Date().toISOString().slice(0, 7),
    lines: order.lineItems.map((li) => ({
      description: li.name,
      sku: li.sku,
      ean: li.ean,
      quantity: li.quantity,
      unit_net_price: li.unitNetPrice,
      vat_rate: vatDecimal(li.vatRate),
    })),
  }, `invoice-${order.number}`, tenantCui);
  if (!invoice.ok) {
    return { status: "INVOICE_DRAFT_FAILED", channel: channelCode, tenant: tenantCui, invoice };
  }

  const idempiereInvoiceId: unknown = null;
  const bpId = partner.body?.idempiere_bpartner_id;
  const postOrderStatus = bpId
    ? "skipped_until_sku_ean_tax_mapping_is_enforced_by_eva_api"
    : "skipped_missing_idempiere_bpartner_id";

  const blPush = await evaPost("/baselinker/push-order", {
    number: order.number,
    email: order.email ?? "",
    customer_name: order.customerName ?? "",
    paid: true,
    lines: order.lineItems.map((li) => ({
      name: li.name,
      qty: li.quantity,
      price_brutto: Number((li.unitNetPrice * (1 + vatDecimal(li.vatRate))).toFixed(2)),
      tax_rate: vatPercent(li.vatRate),
      sku: li.sku ?? "",
    })),
  }, `blpush-${order.number}`, tenantCui);
  return {
    status: "BRIDGED",
    channel: channelCode,
    tenant: tenantCui,
    idempiere_bpartner_id: partner.body?.idempiere_bpartner_id,
    invoice_eva_uuid: invoice.body?.eva_uuid,
    invoice_gross: invoice.body?.gross_total,
    idempiere_invoice_id: idempiereInvoiceId,
    idempiere_post_order: postOrderStatus,
    baselinker: blPush.body?.baselinker?.status ?? blPush.body?.baselinker ?? null,
  };
}

import { createHash } from "crypto";
import { Injectable } from "@nestjs/common";
import { PrismaService } from "../../prisma/prisma.service.js";

type GuardStatus = "processing" | "completed" | "failed";

export type WebhookGuardBegin =
  | { action: "proceed"; payloadHash: string }
  | { action: "replay"; payloadHash: string; response: unknown }
  | { action: "duplicate_processing"; payloadHash: string }
  | { action: "payload_conflict"; payloadHash: string; existingHash: string };

function stableStringify(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return "[" + value.map(stableStringify).join(",") + "]";
  const obj = value as Record<string, unknown>;
  return "{" + Object.keys(obj).sort()
    .map((k) => JSON.stringify(k) + ":" + stableStringify(obj[k]))
    .join(",") + "}";
}

export function hashWebhookPayload(payload: unknown): string {
  return createHash("sha256").update(stableStringify(payload), "utf8").digest("hex");
}

@Injectable()
export class WebhookIdempotencyService {
  constructor(private readonly prisma: PrismaService) {}

  private async ensureTable(): Promise<void> {
    await this.prisma.$executeRawUnsafe(`
      create table if not exists commerce_import_guards (
        id uuid primary key default gen_random_uuid(),
        source_system text not null,
        channel_code text not null,
        external_order_id text not null,
        tenant_cui text,
        payload_hash text not null,
        status text not null,
        response jsonb,
        error jsonb,
        created_at timestamptz not null default now(),
        updated_at timestamptz not null default now(),
        unique(source_system, channel_code, external_order_id)
      );
    `);
  }

  async begin(input: {
    sourceSystem: string;
    channelCode: string;
    externalOrderId: string;
    tenantCui?: string | null;
    payload: unknown;
  }): Promise<WebhookGuardBegin> {
    await this.ensureTable();
    const payloadHash = hashWebhookPayload(input.payload);
    const inserted = await this.prisma.$queryRawUnsafe<Array<{ payload_hash: string }>>(
      `insert into commerce_import_guards
       (source_system, channel_code, external_order_id, tenant_cui, payload_hash, status)
       values ($1,$2,$3,$4,$5,'processing')
       on conflict (source_system, channel_code, external_order_id) do nothing
       returning payload_hash`,
      input.sourceSystem, input.channelCode, input.externalOrderId, input.tenantCui ?? null, payloadHash,
    );
    if (inserted.length > 0) {
      return { action: "proceed", payloadHash };
    }

    const rows = await this.prisma.$queryRawUnsafe<Array<{ payload_hash: string; status: GuardStatus; response: unknown }>>(
      `select payload_hash, status, response from commerce_import_guards
       where source_system=$1 and channel_code=$2 and external_order_id=$3 limit 1`,
      input.sourceSystem, input.channelCode, input.externalOrderId,
    );
    const existing = rows[0];
    if (!existing) {
      return { action: "duplicate_processing", payloadHash };
    }
    if (existing.payload_hash !== payloadHash) {
      return { action: "payload_conflict", payloadHash, existingHash: existing.payload_hash };
    }
    if (existing.status === "completed") {
      return { action: "replay", payloadHash, response: existing.response };
    }
    if (existing.status === "failed") {
      const retried = await this.prisma.$queryRawUnsafe<Array<{ payload_hash: string }>>(
        `update commerce_import_guards
         set status='processing', response=null, error=null, updated_at=now()
         where source_system=$1 and channel_code=$2 and external_order_id=$3
           and payload_hash=$4 and status='failed'
         returning payload_hash`,
        input.sourceSystem, input.channelCode, input.externalOrderId, payloadHash,
      );
      if (retried.length > 0) {
        return { action: "proceed", payloadHash };
      }
    }
    return { action: "duplicate_processing", payloadHash };
  }

  async complete(input: { sourceSystem: string; channelCode: string; externalOrderId: string; response: unknown }): Promise<void> {
    await this.prisma.$executeRawUnsafe(
      `update commerce_import_guards set status='completed', response=$4::jsonb, updated_at=now()
       where source_system=$1 and channel_code=$2 and external_order_id=$3`,
      input.sourceSystem, input.channelCode, input.externalOrderId, JSON.stringify(input.response),
    );
  }

  async fail(input: { sourceSystem: string; channelCode: string; externalOrderId: string; error: unknown }): Promise<void> {
    await this.prisma.$executeRawUnsafe(
      `update commerce_import_guards set status='failed', error=$4::jsonb, updated_at=now()
       where source_system=$1 and channel_code=$2 and external_order_id=$3`,
      input.sourceSystem, input.channelCode, input.externalOrderId, JSON.stringify(input.error),
    );
  }
}

