    @app.route("/app", defaults={"subpath": ""}, methods=["GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"])
    @app.route("/app/<path:subpath>", methods=["GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"])
    def eva_backend_proxy(subpath: str):
        # Public tenant hostnames serve the storefront on this app. Backend/admin
        # routes stay in EVA-Web and are proxied by path only, so the public shop
        # remains on the themed storefront while /app/* reaches the system backend.
        backend = os.environ.get("EVA_WEB_BACKEND_URL", "http://127.0.0.1:4000").rstrip("/")
        target_path = "/app" + (("/" + subpath) if subpath else "")
        target = backend + target_path
        if request.query_string:
            target += "?" + request.query_string.decode("utf-8", "ignore")
        headers = {}
        for key, value in request.headers.items():
            lk = key.lower()
            if lk in {"host", "content-length", "connection", "accept-encoding"}:
                continue
            headers[key] = value
        headers["X-Forwarded-Host"] = request.headers.get("X-Forwarded-Host") or request.host
        headers["X-Forwarded-Proto"] = request.headers.get("X-Forwarded-Proto") or request.scheme
        headers["X-Forwarded-For"] = request.headers.get("X-Forwarded-For") or (request.remote_addr or "")
        body = request.get_data() if request.method not in {"GET", "HEAD"} else None
        req = urllib.request.Request(target, data=body, headers=headers, method=request.method)
        try:
            with _NO_REDIRECT_OPENER.open(req, timeout=30) as resp:
                data = resp.read()
                out_headers = []
                for key, value in resp.headers.items():
                    if key.lower() in {"connection", "transfer-encoding", "content-encoding", "content-length"}:
                        continue
                    out_headers.append((key, value))
                return Response(data, status=resp.status, headers=out_headers)
        except urllib.error.HTTPError as exc:
            data = exc.read()
            out_headers = []
            for key, value in exc.headers.items():
                if key.lower() in {"connection", "transfer-encoding", "content-encoding", "content-length"}:
                    continue
                out_headers.append((key, value))
            return Response(data, status=exc.code, headers=out_headers)
        except urllib.error.URLError as exc:
            return jsonify({"status": "error", "error": "eva_backend_unreachable", "detail": str(exc.reason)}), 502

