def tenant_from_host() -> str:
    host = (request.headers.get("X-Forwarded-Host") or request.host or "").split(":")[0]
    label = host.split(".")[0] if host else ""
    if label in ("", "localhost", "127", "www"):
        return os.environ.get("EVA_DEFAULT_STOREFRONT_TENANT", "cesiro1")
    return label


def request_tenant() -> str:
    host = (request.headers.get("X-Forwarded-Host") or request.host or "").split(":")[0].lower()
    label = host.split(".")[0] if host else ""
    is_local = (
        label in ("", "localhost", "127", "0")
        or host.startswith("127.")
        or host.startswith("localhost")
        or host in ("0.0.0.0", "::1")
    )
    if is_local:
        return request.args.get("tenant") or tenant_from_host()
    return tenant_from_host()


def public_base_url() -> str:
    proto = request.headers.get("X-Forwarded-Proto") or request.scheme or "https"
    host = request.headers.get("X-Forwarded-Host") or request.host
    return f"{proto}://{host}".rstrip("/")


def _sitemap_lastmod() -> str:
    return datetime.now(timezone.utc).date().isoformat()


def _xml_line(name: str, value: str) -> str:
    return f"<{name}>{xml_escape(str(value), quote=True)}</{name}>"


def build_sitemap_xml(tenant: str, base_url: str) -> str:
    rt = cms.runtime(tenant, cms.DEFAULT_LANG, "home", None)
    raw_catalog = cms.catalog(tenant)
    theme_id = str(rt.theme.get("id") or rt.config.get("active_theme") or "")
    langs = list(rt.config.get("languages") or [cms.DEFAULT_LANG])
    lastmod = _sitemap_lastmod()
    urls: list[tuple[str, str, str]] = []
    for lang in langs:
        urls.append((cms.home_url(base_url, rt.tenant, lang, theme_id), "daily", "1.0"))
        for page in cms.legal_pages(rt.tenant):
            urls.append((cms.legal_url(base_url, rt.tenant, lang, theme_id, page), "monthly", "0.4"))
    for product in raw_catalog.get("products", []):
        for lang in langs:
            if cms.localized(product.get("slug"), lang):
                urls.append((cms.product_url(base_url, rt.tenant, lang, theme_id, product), "weekly", "0.8"))
    lines = ['<?xml version="1.0" encoding="UTF-8"?>',
             '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">']
    for loc, changefreq, priority in urls:
        lines.extend([
            "  <url>",
            f"    {_xml_line('loc', loc)}",
            f"    {_xml_line('lastmod', lastmod)}",
            f"    {_xml_line('changefreq', changefreq)}",
            f"    {_xml_line('priority', priority)}",
            "  </url>",
        ])
    lines.append("</urlset>")
    return "\n".join(lines) + "\n"


def build_image_sitemap_xml(tenant: str, base_url: str) -> str:
    rt = cms.runtime(tenant, cms.DEFAULT_LANG, "home", None)
    raw_catalog = cms.catalog(tenant)
    theme_id = str(rt.theme.get("id") or rt.config.get("active_theme") or "")
    lines = [
        '<?xml version="1.0" encoding="UTF-8"?>',
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">',
    ]
    for raw_product in raw_catalog.get("products", []):
        localized = cms.localize_product(raw_product, cms.DEFAULT_LANG, tenant)
        images = [
            image if image.startswith(("http://", "https://")) else base_url.rstrip("/") + image
            for image in (localized.get("images") or [])[:10]
            if image
        ]
        if not images:
            continue
        lines.extend([
            "  <url>",
            f"    {_xml_line('loc', cms.product_url(base_url, rt.tenant, cms.DEFAULT_LANG, theme_id, raw_product))}",
        ])
        for index, image in enumerate(images, start=1):
            caption_label = cms.tr(rt.translations, "image.product_caption", cms.DEFAULT_LANG)
            caption = f"{localized.get('name', '')} - {caption_label} {index}".strip()
            lines.extend([
                "    <image:image>",
                f"      {_xml_line('image:loc', image)}",
                f"      {_xml_line('image:title', localized.get('name', ''))}",
                f"      {_xml_line('image:caption', caption)}",
                "    </image:image>",
            ])
        lines.append("  </url>")
    lines.append("</urlset>")
    return "\n".join(lines) + "\n"

