package com.eva.ro.saga.theme;

/**
 * Structura meniului — COPIATĂ 1:1 din SAGA WEB (instanța de test
 * web0.sagasoft.ro/test, DOM-ul paginii Furnizori, 29.07.2026):
 * cinci meniuri PLATE (fără subgrupe), în ordinea exactă a site-ului:
 * Fisiere · Operatii · Situatii · Diverse · Administrare — cu aceleași
 * etichete (fără diacritice, ca pe site) și aceleași intrări, în aceeași
 * ordine.
 *
 * Excepții minime, marcate: «Inchidere luna» e submeniu (pe site e UN ecran
 * cu butoane pentru TVA/venituri/declarații). Ecranul EvA există acum, deci
 * submeniul ține DOAR ecranul + declarațiile: intrările directe către
 * procesele «Închidere TVA» / «Închidere venituri-cheltuieli» au fost scoase,
 * fiindcă deschideau dialogul brut de proces iDempiere, nu un ecran EvA;
 * «Balante» adăugat după «Carte mare» (lipsește încă din
 * SAGA WEB, dar e nelipsit pentru contabil — există în SAGA C).
 *
 * `targetMenu` = numele intrării AD_Menu care se deschide (mecanismul nativ
 * onMenuSelected). null = încă neimplementat — apare dezactivat, „(în lucru)".
 */
public final class EvaSagaMenuDef {

    public static final class Item {
        public final String label;
        public final String targetMenu;   // numele AD_Menu țintă; null = în lucru
        public final Item[] children;     // gol = frunză
        /**
         * A67b: submeniul se construiește din ARBORELE AD_Menu de sub folderul cu această descriere (ex. «REGES:meniu»,
         * creat de pluginul contab din meniul paginii REGES); {@link #children} rămân doar rezerva, când arborele
         * lipsește pe instanță. null = meniu static.
         */
        public final String arbore;
        Item(String label, String targetMenu, Item[] children) {
            this(label, targetMenu, children, null);
        }
        Item(String label, String targetMenu, Item[] children, String arbore) {
            this.label = label; this.targetMenu = targetMenu; this.children = children; this.arbore = arbore;
        }
        public boolean isLeaf() { return children.length == 0 && arbore == null; }
    }

    private static Item item(String label, String targetMenu) {
        return new Item(label, targetMenu, new Item[0]);
    }
    private static Item menu(String label, Item... children) {
        return new Item(label, null, children);
    }
    /** Meniu construit din arborele AD_Menu de sub folderul cu descrierea {@code arbore}; {@code rezerva} = fără arbore. */
    private static Item arbore(String label, String arbore, Item... rezerva) {
        return new Item(label, null, rezerva, arbore);
    }

    /** Descrierea folderului-rădăcină al meniului REGES (pluginul contab, {@code MeniuReges}). */
    public static final String ARBORE_REGES = "REGES:meniu";

    /** Separatorul căii din numele intrărilor de arbore («REGES › Salariați › Adăugare» → se afișează «Adăugare»). */
    public static final String SEPARATOR_CALE = " › ";

    /** Eticheta afișată a unei intrări de arbore: ultimul segment al căii din nume. */
    public static String etichetaArbore(String nume) {
        if (nume == null)
            return "";
        int i = nume.lastIndexOf(SEPARATOR_CALE);
        return i < 0 ? nume : nume.substring(i + SEPARATOR_CALE.length());
    }

    private EvaSagaMenuDef() { }

    /**
     * Intrările din «Administrare» rezervate ADMINISTRATORULUI (regula utilizatorului, 08.10.2026): configurarea
     * conturilor de acces / parolelor și întreținerea bazei. Tot ce e control și consultare (configurarea societății,
     * parametrii legislativi, fiscalitatea pe luni, calendarul, starea lunilor, verificarea închiderilor, formularele
     * ANAF, seriile) e și al contabilului.
     */
    public static final java.util.Set<String> DOAR_ADMIN = java.util.Set.of("Configurare utilizatori", "Intretinere BD");

    /** «Administrare» văzută de rolul dat: adminul vede tot, ceilalți tot în afară de {@link #DOAR_ADMIN}. */
    public static Item administrarePentru(Item administrare, boolean admin) {
        if (admin)
            return administrare;
        java.util.List<Item> permise = new java.util.ArrayList<>();
        for (Item copil : administrare.children)
            if (!DOAR_ADMIN.contains(copil.label))
                permise.add(copil);
        return new Item(administrare.label, null, permise.toArray(new Item[0]));
    }

