    public static final String SETARE_VALUTA = "EVA_CU_OPERATII_VALUTA";
    public static final String SETARE_CASA_BANCA_VALUTA = "EVA_VALUTA_ASCUNDE_CASA_BANCA";
    /** Țintele (AD_Menu) ascunse cu «Cu operații în valută» = N (help SAGA p. 23, AM8-2) și, în plus, cu «Ascunde și casa / banca» = Y (AM8-3). */
    public static final java.util.Set<String> TINTE_VALUTA = java.util.Set.of("Intrări - valută", "Ieșiri - valută");
    public static final java.util.Set<String> TINTE_CASA_BANCA_VALUTA = java.util.Set.of("Registru de casă — valută", "Jurnal de casă-bancă Valută");

    /**
     * Nodul văzut de firma cu setările date. cuValuta=true ⇒ nodul neschimbat (aceeași instanță). Altfel: frunzele cu targetMenu
     * în TINTE_VALUTA (și, cu ascundeCasaBanca, în TINTE_CASA_BANCA_VALUTA) dispar, recursiv în submeniuri; un submeniu rămas
     * fără copii dispare (null); nodurile «arbore» (REGES) rămân neatinse. D390, «Cursuri valutare» și restul nu se ating (AM8-4).
     * Un nod fără nicio schimbare rămâne aceeași instanță.
     */
    public static Item valutaPentru(Item nod, boolean cuValuta, boolean ascundeCasaBanca) {
        if (cuValuta || nod == null)
            return nod;
        return faraTinte(nod, ascundeCasaBanca);
    }

    private static Item faraTinte(Item nod, boolean ascundeCasaBanca) {
        if (nod.arbore != null)
            return nod;
        if (nod.isLeaf())   // frunzele «în lucru» (targetMenu null) rămân: Set.of(…).contains(null) ar arunca NPE
            return nod.targetMenu != null && (TINTE_VALUTA.contains(nod.targetMenu)
                    || (ascundeCasaBanca && TINTE_CASA_BANCA_VALUTA.contains(nod.targetMenu))) ? null : nod;
        java.util.List<Item> copii = new java.util.ArrayList<>();
        boolean schimbat = false;
        for (Item c : nod.children) {
            Item f = faraTinte(c, ascundeCasaBanca);
            schimbat |= f != c;
            if (f != null)
                copii.add(f);
        }
        if (!schimbat)
            return nod;
        return copii.isEmpty() ? null : new Item(nod.label, nod.targetMenu, copii.toArray(new Item[0]));
    }
